-- Carte cible (KR/TC, sans aucun rattachement)
create temp table tgt on commit drop as
select src.lang, src.set_code, src.num, src.jp_set, src.jp_num, c.id as card_id, c.card_entity_id as singleton_id
from src
join public.sets s on s.language = src.lang and s.code = src.set_code
join public.cards c on c.set_id = s.id and c.number ~ '^0*[0-9]+$' and c.number::int = src.num
where not exists (select 1 from public.card_entity_matches m where m.card_id = c.id);

-- Carte JP cible : famille existante, ancrée sur une carte JP
create temp table jp_tgt on commit drop as
select distinct on (src.lang, src.set_code, src.num, src.jp_set, src.jp_num)
       src.lang, src.set_code, src.num, src.jp_set, src.jp_num, e.id as entity_id
from src
join public.sets js on js.language = 'JP' and js.code = src.jp_set
join public.cards jc on jc.set_id = js.id and jc.number ~ '^0*[0-9]+$' and jc.number::int = src.jp_num
join public.card_entities e on e.anchor_card_id = jc.id
order by src.lang, src.set_code, src.num, src.jp_set, src.jp_num, e.id;

-- Paires candidates (une carte peut en avoir plusieurs)
create temp table pairs_all on commit drop as
select t.card_id, t.singleton_id, j.entity_id
from tgt t
join jp_tgt j on j.lang = t.lang and j.set_code = t.set_code and j.num = t.num
             and j.jp_set = t.jp_set and j.jp_num = t.jp_num;

-- Paires finales : une carte -> UNE seule famille. Les cartes avec deux familles
-- candidates différentes sont écartées (ambiguës), jamais rattachées au hasard.
create temp table pairs on commit drop as
select card_id, (array_agg(distinct singleton_id))[1] as singleton_id, (array_agg(distinct entity_id))[1] as entity_id
from pairs_all
group by card_id
having count(distinct entity_id) = 1;

create temp table rapport (ordre int, controle text, n bigint) on commit drop;
insert into rapport
select 1, 'cartes SC sans rattachement ciblées', count(*) from tgt
union all select 2, 'familles JP trouvées', count(distinct entity_id) from pairs_all
union all select 3, 'paires à rattacher', count(*) from pairs
union all select 4, 'lignes AUTO sans carte ou sans famille JP', (select count(*) from src) - (select count(*) from pairs_all)
union all select 6, 'cartes ambiguës écartées (plusieurs familles JP)', (select count(*) from (select card_id from pairs_all group by card_id having count(distinct entity_id) > 1) x);

insert into public.card_entity_matches (card_entity_id, card_id, match_method, confidence, status, evidence)
select p.entity_id, p.card_id, 'empreinte', 90, 'auto',
       jsonb_build_object('regle', 'empreinte : espèce, PV, retraite, attaques, illustrateur')
from pairs p
on conflict (card_id) do nothing;

update public.cards c set card_entity_id = p.entity_id
from pairs p
where c.id = p.card_id;

-- Supprimer la famille individuelle devenue inutile
delete from public.card_entities e
using pairs p
where e.id = p.singleton_id
  and not exists (select 1 from public.cards c where c.card_entity_id = e.id)
  and not exists (select 1 from public.card_entity_matches m where m.card_entity_id = e.id);

insert into rapport
select 5, 'rattachements KR/TC/SC après écriture (total)',
       (select count(*) from public.card_entity_matches m join public.cards c on c.id = m.card_id
          join public.sets s on s.id = c.set_id where s.language in ('KR','TC','SC'));

select * from rapport order by ordre;

commit;
